:root {
    --paper: #faf6ec;
    --paper-card: #fffdf7;
    --paper-card-2: #f2ecdd;
    --ink: #2a241c;
    --ink-soft: #6b6255;
    --border: #e6ddc7;
    --indigo: #413d8a;
    --indigo-dark: #2e2a66;
    --indigo-soft: rgba(65, 61, 143, 0.08);
    --gold: #b9852c;
    --forest: #2f6b4f;
    --plum: #7a3f63;
    --hub-fill: #c9c4ef;
    --hub-text: #221f52;
    --done-fill: #bfe4d2;
    --done-text: #123722;
    --sidebar-w: 290px;
}
* {
    box-sizing: border-box;
}
html {
    scroll-behavior: smooth;
}
body {
    margin: 0;
    background: var(--paper);
    color: var(--ink);
    font-family:
        'Noto Sans JP',
        system-ui,
        -apple-system,
        sans-serif;
    line-height: 1.85;
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
}
.layout {
    display: block;
}
a {
    color: var(--indigo-dark);
}
h1,
h2,
h3,
h4 {
    font-family: 'Noto Sans JP', system-ui, sans-serif;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.4;
}
.accent-serif {
    font-family: 'Source Serif 4', serif;
}

/* ---------- Sidebar ---------- */
.sidebar {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: var(--sidebar-w);
    background: var(--paper-card);
    border-right: 1px solid var(--border);
    overflow-y: auto;
    padding: 1.75rem 1.25rem 3rem;
    z-index: 50;
}
.sidebar-title {
    font-family: 'Source Serif 4', serif;
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--indigo-dark);
    margin: 0 0 0.2rem;
}
.sidebar-sub {
    font-size: 1rem;
    color: var(--ink-soft);
    margin: 0 0 1.5rem;
}
.nav-group-label {
    font-size: 1rem;
    letter-spacing: 0.05em;
    color: var(--ink-soft);
    text-transform: uppercase;
    margin: 1.1rem 0 0.4rem;
    padding-left: 0.6rem;
    font-weight: 700;
}
.sidebar ul,
.sidebar nav ul {
    list-style: none;
    margin: 0;
    padding: 0;
}
.sidebar li {
    list-style: none;
}
.nav-a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.5rem 0.6rem;
    border-radius: 0.5rem;
    color: var(--ink-soft);
    text-decoration: none;
    font-size: 1rem;
    transition:
        background 0.15s,
        color 0.15s;
}
.nav-a i {
    font-size: 1.05rem;
    color: var(--indigo);
    flex-shrink: 0;
}
.nav-a:hover {
    background: var(--indigo-soft);
    color: var(--ink);
}
.nav-a.active {
    background: var(--indigo-soft);
    color: var(--indigo-dark);
    font-weight: 700;
}
.n-num {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.7rem;
    height: 1.7rem;
    border-radius: 50%;
    background: var(--paper-card-2);
    color: var(--ink-soft);
    font-size: 1rem;
    font-weight: 700;
    flex-shrink: 0;
}
.nav-a.active .n-num {
    background: var(--indigo);
    color: #fff;
}

/* ---------- Main ---------- */
.main {
    margin-left: var(--sidebar-w);
    min-height: 100vh;
}
.content {
    padding: 0 3rem 5rem;
    max-width: none;
}
.content p,
.content li {
    overflow-wrap: break-word;
}

.hero {
    padding: 3.5rem 3rem 2.5rem;
    background: linear-gradient(
        135deg,
        var(--indigo-dark),
        var(--indigo) 60%,
        var(--plum)
    );
    color: #fdfbf6;
}
.hero-kicker {
    font-size: 1rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    opacity: 0.85;
    margin: 0 0 0.8rem;
    font-weight: 700;
}
.hero h1 {
    font-family: 'Source Serif 4', serif;
    color: #fff;
    font-size: 2.3rem;
    line-height: 1.35;
    margin: 0 0 1rem;
    font-weight: 700;
}
.hero p {
    font-size: 1.05rem;
    opacity: 0.92;
    max-width: 56rem;
    margin: 0;
}

section {
    padding: 3rem 0;
    border-bottom: 1px solid var(--border);
}
section:last-of-type {
    border-bottom: none;
}
.sec-head {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    margin-bottom: 1.4rem;
}
.sec-head i {
    font-size: 1.4rem;
    color: #fff;
    background: var(--indigo);
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.7rem;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}
.sec-head h2 {
    font-size: 1.5rem;
    margin: 0;
}
.sec-head .n-badge {
    font-family: 'Source Serif 4', serif;
    font-weight: 700;
    color: var(--ink-soft);
    font-size: 1rem;
}

blockquote {
    margin: 1.5rem 0;
    padding: 1rem 1.4rem;
    background: var(--paper-card-2);
    border-left: 4px solid var(--gold);
    border-radius: 0.4rem;
    color: var(--ink);
}
strong {
    color: var(--indigo-dark);
}

/* ---------- Tables ---------- */
.table-wrap {
    overflow-x: auto;
    overflow-y: hidden;
    border: 1px solid var(--border);
    border-radius: 0.6rem;
    margin: 1.5rem 0;
    background: var(--paper-card);
}
.table-title {
    background: var(--paper-card-2);
    color: var(--ink);
    font-weight: 700;
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--border);
    font-size: 1rem;
}
table {
    border-collapse: collapse;
    width: 100%;
    font-size: 1rem;
}
th,
td {
    padding: 0.7rem 0.9rem;
    text-align: left;
    border-bottom: 1px solid var(--border);
}
thead th {
    background: var(--indigo-dark);
    color: #fff;
    font-weight: 700;
    white-space: nowrap;
}
tbody tr:nth-child(even) {
    background: rgba(65, 61, 143, 0.045);
}
tbody tr:hover {
    background: var(--indigo-soft);
}

.kv-table th {
    background: transparent;
    color: var(--ink-soft);
    font-weight: 700;
    border-right: 1px solid var(--border);
    width: 11rem;
    white-space: nowrap;
}
.kv-table tr:hover {
    background: var(--indigo-soft);
}
.kv-table tbody tr:nth-child(even) {
    background: transparent;
}

/* ---------- Mermaid diagrams ---------- */
.diagram-block {
    margin: 1.8rem 0;
}
.diagram-caption {
    font-size: 1rem;
    color: var(--ink-soft);
    margin-bottom: 0.6rem;
    font-weight: 500;
}
.mermaid-wrapper {
    width: 100%;
    display: flex;
    justify-content: safe center;
    overflow-x: auto;
    padding: 1.2rem;
    background: var(--paper-card);
    border: 1px solid var(--border);
    border-radius: 0.8rem;
}
.mermaid-wrapper svg {
    flex-shrink: 0;
}
.diagram-loading {
    font-size: 1rem;
    color: var(--ink-soft);
    padding: 2rem;
    text-align: center;
    width: 100%;
}

/* ---------- Checklist ---------- */
.checklist {
    list-style: none;
    margin: 1.5rem 0;
    padding: 0;
}
.checklist li {
    display: flex;
    align-items: flex-start;
    gap: 0.8rem;
    padding: 0.8rem 1rem;
    border: 1px solid var(--border);
    border-radius: 0.6rem;
    margin-bottom: 0.6rem;
    background: var(--paper-card);
    transition: background 0.15s;
}
.checklist li.done {
    background: var(--indigo-soft);
}
.checklist li.done label,
.checklist input[type='checkbox']:checked + label {
    text-decoration: line-through;
    color: var(--ink-soft);
}
.checklist input[type='checkbox'] {
    appearance: none;
    -webkit-appearance: none;
    width: 1.3rem;
    height: 1.3rem;
    border: 2px solid var(--indigo);
    border-radius: 0.35rem;
    flex-shrink: 0;
    margin-top: 0.15rem;
    cursor: pointer;
    position: relative;
}
.checklist input[type='checkbox']:checked {
    background: var(--indigo);
}
.checklist input[type='checkbox']:checked::after {
    content: '';
    position: absolute;
    left: 0.32rem;
    top: 0.05rem;
    width: 0.35rem;
    height: 0.7rem;
    border: solid #fff;
    border-width: 0 2px 2px 0;
    transform: rotate(45deg);
}
.checklist label {
    cursor: pointer;
    font-size: 1rem;
    line-height: 1.6;
}
.checklist-counter {
    display: inline-block;
    margin-bottom: 1rem;
    padding: 0.4rem 1rem;
    background: var(--gold);
    color: #fff;
    border-radius: 2rem;
    font-weight: 700;
    font-size: 1rem;
}

/* ---------- Reference cards ---------- */
.ref-list {
    display: flex;
    flex-direction: column;
    gap: 0.9rem;
    margin-top: 1.5rem;
}
.ref-card {
    border: 1px solid var(--border);
    border-radius: 0.7rem;
    padding: 0.9rem 1.1rem;
    background: var(--paper-card);
}
.ref-card .ref-title {
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.25rem;
    font-size: 1rem;
}
.ref-card .ref-note {
    color: var(--ink-soft);
    font-size: 1rem;
    margin-bottom: 0.4rem;
}
.ref-card .ref-url {
    font-size: 1rem;
    color: var(--indigo-dark);
    word-break: break-all;
}

/* ---------- Tags ---------- */
.tag {
    display: inline-block;
    padding: 0.15rem 0.7rem;
    border-radius: 1rem;
    background: var(--indigo-soft);
    color: var(--indigo-dark);
    font-size: 1rem;
    font-weight: 700;
    margin-right: 0.4rem;
}

/* ---------- Footer ---------- */
.footer {
    padding: 2.5rem 3rem;
    color: var(--ink-soft);
    font-size: 1rem;
    border-top: 1px solid var(--border);
}

/* ---------- Mobile ---------- */
.mobile-bar,
.mobile-bar * {
    font-size: 1rem;
}
.mobile-bar {
    display: none;
    position: sticky;
    top: 0;
    z-index: 60;
    background: var(--paper-card);
    border-bottom: 1px solid var(--border);
    padding: 0.8rem 1rem;
    align-items: center;
    justify-content: space-between;
}
.mobile-bar .m-title {
    font-weight: 700;
    color: var(--indigo-dark);
}
#mobileToggle {
    background: var(--indigo);
    color: #fff;
    border: none;
    border-radius: 0.5rem;
    width: 2.4rem;
    height: 2.4rem;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}
sup {
    font-size: 1rem;
    vertical-align: super;
    line-height: 0;
}

@media (max-width: 960px) {
    .mobile-bar {
        display: flex;
    }
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.2s ease;
        box-shadow: 0 0 30px rgba(0, 0, 0, 0.25);
    }
    .sidebar.open {
        transform: translateX(0);
    }
    .main {
        margin-left: 0;
    }
    .content {
        padding: 0 1.2rem 3rem;
    }
    .hero {
        padding: 2rem 1.2rem;
    }
    .hero h1 {
        font-size: 1.6rem;
    }
    .footer {
        padding: 2rem 1.2rem;
    }
}
